document.addEventListener("DOMContentLoaded",function(){let a=document.querySelectorAll("[data-target]");a.forEach(function(n){n.addEventListener("click",function(e){e.stopPropagation();let t=document.getElementById(n.dataset.target);if(!t)return;let i=!t.classList.contains("hidden");a.forEach(function(d){if(d===n)return;let c=document.getElementById(d.dataset.target);c&&c.classList.add("hidden")}),t.classList.toggle("hidden",i)})}),document.addEventListener("click",function(n){a.forEach(function(e){let t=document.getElementById(e.dataset.target);t&&!t.contains(n.target)&&!e.contains(n.target)&&t.classList.add("hidden")})})});
